-- TechQuest Room quiz attempts (PostgreSQL)
-- Execute manually after inspecting the live schema. This is not an EF migration.
-- Existing Professor_uploads and Room_result rows are preserved.

ALTER TABLE "Professor_uploads"
    ADD COLUMN IF NOT EXISTS "MaxAttempts" integer NOT NULL DEFAULT 3;

ALTER TABLE "Professor_uploads"
    ADD CONSTRAINT "CK_Professor_uploads_MaxAttempts_Positive"
    CHECK ("MaxAttempts" > 0) NOT VALID;

CREATE TABLE IF NOT EXISTS "Room_quiz_attempts" (
    "RoomQuizAttemptId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "RoomId" integer NOT NULL,
    "StudentId" integer NOT NULL,
    "ClientRequestId" uuid NOT NULL,
    "StartedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "CompletedAt" timestamp with time zone NULL,
    CONSTRAINT "FK_Room_quiz_attempts_Multiplayer_room_RoomId"
        FOREIGN KEY ("RoomId") REFERENCES "Multiplayer_room" ("RoomId") ON DELETE CASCADE,
    CONSTRAINT "FK_Room_quiz_attempts_Student_profile_StudentId"
        FOREIGN KEY ("StudentId") REFERENCES "Student_profile" ("StudentId") ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Room_quiz_attempts_RoomId_StudentId_ClientRequestId"
    ON "Room_quiz_attempts" ("RoomId", "StudentId", "ClientRequestId");

CREATE INDEX IF NOT EXISTS "IX_Room_quiz_attempts_RoomId_StudentId"
    ON "Room_quiz_attempts" ("RoomId", "StudentId");

ALTER TABLE "Room_result"
    ADD COLUMN IF NOT EXISTS "RoomQuizAttemptId" integer NULL;

-- The old one-result-per-room/student index would prevent a second attempt.
DROP INDEX IF EXISTS "IX_Room_result_RoomId_StudentId";

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Room_result_RoomId_StudentId_RoomQuizAttemptId"
    ON "Room_result" ("RoomId", "StudentId", "RoomQuizAttemptId");

ALTER TABLE "Room_result"
    ADD CONSTRAINT "FK_Room_result_Room_quiz_attempts_RoomQuizAttemptId"
    FOREIGN KEY ("RoomQuizAttemptId")
    REFERENCES "Room_quiz_attempts" ("RoomQuizAttemptId")
    ON DELETE CASCADE;
